const labelMap={starter:'구분',name:'선수',team:'팀',pos:'포지션',energy:'체력',age:'나이',no:'#',ovr:'오버롤',pot:'포텐',pa:'타석',ab:'타수',avg:'타율',obp:'출루율',slg:'장타율',h:'안타',hr:'홈런',doubles:'2루타',triples:'3루타',k:'삼진',bb:'볼넷',sb:'도루 성공',attempts:'도루 시도',ops:'OPS',rbi:'타점',babip:'BABIP',iso:'ISO',bbRate:'BB%',kRate:'K%',g:'경기',gs:'선발',w:'승',l:'패',sv:'SV',hld:'HLD',ip:'이닝',ha:'피안타',er:'자책점',r:'실점',hp:'사구',era:'ERA',whip:'WHIP',k9:'K/9',bb9:'BB/9',war:'WAR',move:'선수 이동',rank:'순위'};
