function val(p,k){if(p.pitcher===true&&['avg','ops','obp','slg','pa','ab','h','doubles','triples','sb','attempts'].includes(k))return '—';if(p.pitcher===false&&['era','whip','w','l','sv','hld','gs','ip','ha','er','r','hp','k9','bb9'].includes(k))return '—';if(k==='starter')return state.order.includes(p.id)?'<span class="starter starter-on">선발</span>':'<span class="starter">후보</span>';if(k==='pos')return pos(p);if(k==='energy')return energy(p);if(k==='name')return esc(p.name);if(k==='ovr'||k==='pot')return rating(p[k])+delta(p,k);if(['avg','obp','slg','ops','babip','iso'].includes(k))return Number(p[k]).toFixed(3);if(['era','whip'].includes(k))return Number(p[k]).toFixed(2);if(k==='war'&&p.war==null)return '—';if(['k9','bb9','ip','war'].includes(k))return Number(p[k]).toFixed(1);if(['bbRate','kRate'].includes(k))return (p[k]*100).toFixed(1)+'%';if(k==='move')return `<select data-move="${p.id}" aria-label="${p.name} 선수 이동">${[['first','1군'],['second','2군'],['injured','부상자 명단']].map(([g,l])=>`<option value="${g}" ${p.group===g?'selected':''}>${l}</option>`).join('')}</select>`;return esc(p[k]??'—');}
function table(id,players,cols,{draggable=false,max='',empty='표시할 선수가 없습니다.'}={}){const s=sorts[id];let rows=[...players];if(s)rows.sort((a,b)=>{if(s.key==='pos')return comparePosition(a,b)*s.dir;const x=s.key==='starter'?Number(state.order.includes(a.id)):a[s.key],y=s.key==='starter'?Number(state.order.includes(b.id)):b[s.key];return (typeof x==='number'?x-y:String(x).localeCompare(String(y),'ko'))*s.dir;});if(id.startsWith('records-')&&s&&s.key!=='rank')rows=rows.map((p,i)=>({...p,rank:i+1}));return `<div class="tablewrap" ${max?`style="max-height:${max}"`:''}><table data-table="${id}"><thead><tr>${cols.map(k=>`<th class="${['name','team','pos'].includes(k)?'name':''}" ${s?.key===k?`aria-sort="${s.dir===1?'ascending':'descending'}"`:''}>${k==='move'?labelMap[k]:`<button data-sort="${id}:${k}" aria-label="${labelMap[k]} 정렬">${labelMap[k]} ${s?.key===k?(s.dir===1?'↑':'↓'):'↕'}</button>`}</th>`).join('')}</tr></thead><tbody>${rows.map(p=>`<tr ${draggable?`draggable="true" data-player="${p.id}" class="sortable"`:''}>${cols.map(k=>`<td class="${['name','team','pos'].includes(k)?'name':''}">${val(p,k)}</td>`).join('')}</tr>`).join('')}</tbody></table>${rows.length?'':`<div class="empty">${empty}</div>`}</div>`;}
const coords={LF:[22,20],CF:[50,13],RF:[78,20],SS:[36,44],'2B':[64,44],'3B':[20,64],'1B':[80,64],C:[50,81],DH:[12,88]};
