function orderTable(){const players=state.order.map(byId).filter(Boolean);return `<div class="tablewrap orderwrap"><table><thead><tr>${['타순','선수','체력','OVR','POT','AVG','OBP','OPS','HR','RBI','BB'].map(l=>`<th>${l}</th>`).join('')}</tr></thead><tbody>${players.map((p,i)=>`<tr draggable="true" class="sortable" data-order="${p.id}" data-player="${p.id}"><td><span class="draghandle">⠿</span> &nbsp; ${i+1}</td><td class="name">${p.name}<small class="muted"> &nbsp; ${positions.find(k=>state.field[k]===p.id)||p.pos}</small></td><td>${energy(p)}</td><td>${rating(p.ovr)}</td><td>${rating(p.pot)}</td><td>${p.avg.toFixed(3)}</td><td>${p.obp.toFixed(3)}</td><td>${p.ops.toFixed(3)}</td><td>${p.hr}</td><td>${p.rbi}</td><td>${p.bb}</td></tr>`).join('')}</tbody></table></div>${players.length<9?'<div class="note">빈 수비 위치에 선수를 배치해 타순을 완성하세요.</div>':''}`;}
function batters(){const bench=first().filter(p=>!p.pitcher&&!state.order.includes(p.id));return `<div class="lineupgrid">${panel('수비 포지션 & 선발 선수',`<div class="field"><svg viewBox="0 0 600 380" preserveAspectRatio="none" aria-hidden="true"><path d="M300 343 L40 100 Q300 -85 560 100 Z" fill="none" stroke="#91b59d" stroke-width="2"/><path d="M300 322 176 220 300 118 424 220Z" fill="#74694d" stroke="#99a487"/><path d="M300 299 204 220 300 141 396 220Z" fill="#244736"/><path d="M300 343 64 143 M300 343 536 143" stroke="#ccdac4" stroke-width="2"/><circle cx="300" cy="235" r="13" fill="#a29772"/><path d="M293 317h14v10l-7 6-7-6Z" fill="#d8dfc7"/></svg>${positions.map(p=>card(byId(state.field[p]),p,true)).join('')}<span class="fieldlabel">DEFENSIVE ALIGNMENT</span></div><div class="bench"><span class="benchlabel">BENCH</span>${bench.map(p=>card(p,p.pos)).join('')||'<span class="empty">후보 선수가 없습니다.</span>'}</div>`,'<small>지명타자 포함 · 9명</small>')}${panel('타순',orderTable(),'<span class="tag">실시간 반영</span>')}</div>${panel('1군 타자 전체',table('batters',first().filter(p=>!p.pitcher),batCols,{draggable:true}),`<small>${first().filter(p=>!p.pitcher).length}명</small>`)}`;}
